1	import "./load-env";
2	import { readFileSync, existsSync } from "fs";
3	import { resolve } from "path";
4	import { createInterface } from "readline";
5	import { marked } from "marked";
6	import matter from "gray-matter";
7	import { CakemailClient } from "./cakemail-client";
8	import {
9	  renderWrappedHtml,
10	  transformObsidianCallouts,
11	} from "./render-email";
12	import {
13	  NEWSLETTER_SUBSCRIBERS_LIST_ID,
14	  SENDER_ID_MARK,
15	} from "../../shared/cakemail-constants";
16	
17	const WRAPPER_PATH = resolve(
18	  __dirname,
19	  "../templates/course/post-wrapper.html",
20	);
21	const DEFAULT_COURSES_PATH = resolve(
22	  __dirname,
23	  "../newsletters/courses.json",
24	);
25	
26	// --- Greeting ---
27	//
28	// The personalised greeting is owned by the code, NOT the author. Authors write
29	// only the body; this guarantees a correct Cakemail merge tag ships every time
30	// and removes the class of human error that mailed the whole list a literal
31	// "Hi [firstname,]," on 2026-06-26.
32	//
33	// `[firstname]` with NO comma is Cakemail's "no fallback" form: it renders the
34	// contact's first name, or blank when there isn't one. NEVER write an empty
35	// fallback "[firstname,]" — that is malformed and Cakemail prints the tag
36	// verbatim. A fallback word ("[firstname,there]") is deliberately not used:
37	// Mark prefers a bare greeting over a generic placeholder. (A contact with no
38	// first name therefore sees "Hi ," — to drop the dangling comma, change
39	// GREETING to `Hi ${FIRST_NAME_TAG}`.)
40	const FIRST_NAME_TAG = "[firstname]";
41	const GREETING = `Hi ${FIRST_NAME_TAG},`;
42	
43	/**
44	 * Prepend the canonical greeting to the newsletter body.
45	 *
46	 * If the author still hand-wrote a greeting (out of habit, correct or
47	 * malformed), drop it first: a leading non-empty line containing "firstname"
48	 * (case-insensitive) is a merge-tag greeting attempt — that substring never
49	 * occurs in normal newsletter prose — so it is replaced rather than doubled.
50	 */
51	function withGreeting(bodyMarkdown: string): string {
52	  const lines = bodyMarkdown.split("\n");
53	  let start = 0;
54	  while (start < lines.length && lines[start].trim() === "") start += 1;
55	  if (start < lines.length && /firstname/i.test(lines[start])) {
56	    let end = start + 1;
57	    while (end < lines.length && lines[end].trim() === "") end += 1;
58	    lines.splice(start, end - start);
59	  }
60	  return `${GREETING}\n\n${lines.join("\n").trimStart()}`;
61	}
62	
63	// --- Types ---
64	
65	interface CliArgs {
66	  contentPath: string;
67	  coursesPath: string;
68	  testSend?: string;
69	  send: boolean;
70	  scheduleDay?: string;
71	  allowPastCourses: boolean;
72	  keepOnError: boolean;
73	}
74	
75	interface NewsletterFrontmatter {
76	  subject: string;
77	  date: string | Date;
78	}
79	
80	interface ParsedNewsletter {
81	  subject: string;
82	  date: string;
83	  bodyMarkdown: string;
84	}
85	
86	interface CourseEntry {
87	  type: string;
88	  date: string;
89	  dateFormatted: string;
90	  location: string;
91	  url: string;
92	}
93	
94	interface CoursesConfig {
95	  courses: CourseEntry[];
96	}
97	
98	// --- CLI ---
99	
100	function printUsage(): void {
101	  console.log(`
102	Usage:
103	  npm run send-newsletter -- --content newsletters/<file>.md [options]
104	
105	Options:
106	  --content             Path to the newsletter markdown file (required)
107	  --courses             Path to courses JSON (default: newsletters/courses.json)
108	  --test-send <email>   Create the draft, then send a test copy to <email>. This
109	                        is how you preview: review it in your inbox and in the
110	                        Cakemail UI. Preview-only; cannot combine with --send or
111	                        --schedule (dispatch in a separate run).
112	  --send                After creating the draft (and any test), schedule for
113	                        immediate delivery. Prompts for confirmation.
114	  --schedule <day>      After creating the draft (and any test), schedule
115	                        delivery for the next Mon|Tue|Wed|Thu|Fri at 10:00 AM
116	                        Eastern. No confirmation prompt. Cannot combine with
117	                        --send.
118	  --allow-past-courses  Skip the stale-course validation
119	  --keep-on-error       On failure, leave the draft in Cakemail for inspection
120	                        (default: delete draft so the UI stays tidy)
121	  --help                Show this help
122	
123	Workflow without --send (default):
124	  Creates a draft campaign in Cakemail. Review in the Cakemail UI and send
125	  from there, or re-run with --send once you are sure.
126	`);
127	}
128	
129	function parseArgs(): CliArgs {
130	  const args = process.argv.slice(2);
131	  if (args.includes("--help") || args.includes("-h")) {
132	    printUsage();
133	    process.exit(0);
134	  }
135	
136	  function getArg(name: string): string | undefined {
137	    const idx = args.indexOf(name);
138	    if (idx === -1 || idx + 1 >= args.length) return undefined;
139	    return args[idx + 1];
140	  }
141	
142	  const contentPath = getArg("--content");
143	  if (!contentPath) {
144	    console.error("Error: --content is required.");
145	    printUsage();
146	    process.exit(1);
147	  }
148	
149	  const scheduleDay = getArg("--schedule");
150	  const send = args.includes("--send");
151	  const testSend = getArg("--test-send");
152	  if (send && scheduleDay) {
153	    console.error(
154	      "Error: --send (immediate) and --schedule (future) are mutually exclusive.",
155	    );
156	    process.exit(1);
157	  }
158	  // --test-send is preview-only. Combining it with a dispatch flag is what
159	  // makes "I only tested it" actually commit a send. Force a separate run.
160	  if (testSend && (send || scheduleDay)) {
161	    console.error(
162	      "Error: --test-send is preview-only and cannot combine with --send or --schedule.\n" +
163	        "       Preview first, then dispatch in a separate run.",
164	    );
165	    process.exit(1);
166	  }
167	
168	  return {
169	    contentPath,
170	    coursesPath: getArg("--courses") ?? DEFAULT_COURSES_PATH,
171	    testSend,
172	    send,
173	    scheduleDay,
174	    allowPastCourses: args.includes("--allow-past-courses"),
175	    keepOnError: args.includes("--keep-on-error"),
176	  };
177	}
178	
179	// --- Schedule resolution ---
180	//
181	// `--schedule <day>` resolves to the soonest 10:00 AM Eastern on that weekday
182	// still in the future. The America/New_York IANA zone keeps "10am Eastern"
183	// correct year-round (EDT/UTC-4 in summer, EST/UTC-5 in winter).
184	
185	const SCHEDULE_TZ = "America/New_York";
186	const SEND_HOUR_ET = 10;
187	const WEEKDAY_INDEX: Record<string, number> = {
188	  mon: 1,
189	  tue: 2,
190	  wed: 3,
191	  thu: 4,
192	  fri: 5,
193	};
194	
195	interface ScheduledSend {
196	  unixSeconds: number;
197	  label: string; // human-readable ET datetime, for logging
198	}
199	
200	/** Read numeric date/time parts of an instant as rendered in `timeZone`. */
201	function zonedParts(
202	  timeZone: string,
203	  at: Date,
204	  options: Intl.DateTimeFormatOptions,
205	): Record<string, number> {
206	  const parts: Record<string, number> = {};
207	  for (const p of new Intl.DateTimeFormat("en-US", {
208	    timeZone,
209	    hour12: false,
210	    ...options,
211	  }).formatToParts(at)) {
212	    if (p.type !== "literal") parts[p.type] = Number(p.value);
213	  }
214	  return parts;
215	}
216	
217	/** UTC ms for a wall-clock time in `timeZone`, DST-correct. */
218	function wallClockToUtcMs(
219	  year: number,
220	  month0: number,
221	  day: number,
222	  hour: number,
223	  timeZone: string,
224	): number {
225	  const offsetMs = (ms: number): number => {
226	    const p = zonedParts(timeZone, new Date(ms), {
227	      year: "numeric",
228	      month: "2-digit",
229	      day: "2-digit",
230	      hour: "2-digit",
231	      minute: "2-digit",
232	      second: "2-digit",
233	    });
234	    const asUtc = Date.UTC(
235	      p.year,
236	      p.month - 1,
237	      p.day,
238	      p.hour % 24,
239	      p.minute,
240	      p.second,
241	    );
242	    return asUtc - ms;
243	  };
244	  let ms = Date.UTC(year, month0, day, hour, 0, 0);
245	  const o1 = offsetMs(ms);
246	  ms -= o1;
247	  const o2 = offsetMs(ms);
248	  if (o2 !== o1) ms += o1 - o2;
249	  return ms;
250	}
251	
252	function resolveSchedule(dayArg: string): ScheduledSend {
253	  const target = WEEKDAY_INDEX[dayArg.trim().toLowerCase().slice(0, 3)];
254	  if (target === undefined) {
255	    console.error(
256	      `Error: --schedule must be one of Mon, Tue, Wed, Thu, Fri (got "${dayArg}")`,
257	    );
258	    process.exit(1);
259	  }
260	
261	  const now = new Date();
262	  const et = zonedParts(SCHEDULE_TZ, now, {
263	    year: "numeric",
264	    month: "2-digit",
265	    day: "2-digit",
266	    hour: "2-digit",
267	  });
268	  // 00:00-UTC anchor on ET's "today", safe for whole-day arithmetic.
269	  const anchor = Date.UTC(et.year, et.month - 1, et.day);
270	  const todayDow = new Date(anchor).getUTCDay();
271	
272	  for (let i = 0; i <= 7; i++) {
273	    if ((todayDow + i) % 7 !== target) continue;
274	    if (i === 0 && et.hour % 24 >= SEND_HOUR_ET) continue; // 10am ET already passed
275	    const d = new Date(anchor + i * 86_400_000);
276	    const ms = wallClockToUtcMs(
277	      d.getUTCFullYear(),
278	      d.getUTCMonth(),
279	      d.getUTCDate(),
280	      SEND_HOUR_ET,
281	      SCHEDULE_TZ,
282	    );
283	    const label = new Intl.DateTimeFormat("en-US", {
284	      timeZone: SCHEDULE_TZ,
285	      weekday: "long",
286	      year: "numeric",
287	      month: "long",
288	      day: "numeric",
289	      hour: "numeric",
290	      minute: "2-digit",
291	      timeZoneName: "short",
292	    }).format(new Date(ms));
293	    return { unixSeconds: Math.floor(ms / 1000), label };
294	  }
295	  // Unreachable: a weekday always recurs within 7 days.
296	  throw new Error("Could not resolve schedule date");
297	}
298	
299	// --- Newsletter parsing ---
300	
301	function parseNewsletter(filePath: string): ParsedNewsletter {
302	  if (!existsSync(filePath)) {
303	    console.error(`Error: newsletter file not found: ${filePath}`);
304	    process.exit(1);
305	  }
306	
307	  const raw = readFileSync(filePath, "utf-8");
308	  const { data, content } = matter(raw);
309	  const fm = data as NewsletterFrontmatter;
310	
311	  if (!fm.subject) {
312	    console.error("Error: frontmatter must include 'subject'");
313	    process.exit(1);
314	  }
315	  // gray-matter auto-parses YAML dates; coerce back to YYYY-MM-DD string.
316	  const dateStr =
317	    fm.date instanceof Date ? fm.date.toISOString().slice(0, 10) : String(fm.date ?? "");
318	  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
319	    console.error("Error: frontmatter must include 'date' in YYYY-MM-DD format");
320	    process.exit(1);
321	  }
322	
323	  return {
324	    subject: String(fm.subject).trim(),
325	    date: dateStr,
326	    bodyMarkdown: content.trim(),
327	  };
328	}
329	
330	// --- Courses ---
331	
332	function todayYMD(): string {
333	  const d = new Date();
334	  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
335	}
336	
337	function loadCourses(coursesPath: string, allowPast: boolean): CourseEntry[] {
338	  if (!existsSync(coursesPath)) {
339	    console.error(
340	      `Error: courses file not found at ${coursesPath}. Every newsletter must include an Upcoming Courses block.`,
341	    );
342	    process.exit(1);
343	  }
344	
345	  let config: CoursesConfig;
346	  try {
347	    config = JSON.parse(readFileSync(coursesPath, "utf-8"));
348	  } catch (err) {
349	    console.error(`Error: failed to parse ${coursesPath}: ${String(err)}`);
350	    process.exit(1);
351	  }
352	
353	  const courses = config.courses ?? [];
354	  if (courses.length === 0) {
355	    console.error(
356	      `Error: ${coursesPath} has no courses. Every newsletter must include an Upcoming Courses block.`,
357	    );
358	    process.exit(1);
359	  }
360	
361	  // Validate each entry has the fields we use.
362	  for (const c of courses) {
363	    if (!c.type || !c.date || !c.dateFormatted || !c.location || !c.url) {
364	      console.error(
365	        `Error: course entry is missing a required field (type, date, dateFormatted, location, url): ${JSON.stringify(c)}`,
366	      );
367	      process.exit(1);
368	    }
369	    if (!/^\d{4}-\d{2}-\d{2}$/.test(c.date)) {
370	      console.error(
371	        `Error: course 'date' must be YYYY-MM-DD (got "${c.date}" on ${c.type})`,
372	      );
373	      process.exit(1);
374	    }
375	  }
376	
377	  const today = todayYMD();
378	  const stale = courses.filter((c) => c.date < today);
379	  if (stale.length > 0 && !allowPast) {
380	    console.error(
381	      `Error: ${stale.length} course(s) in ${coursesPath} have already started:`,
382	    );
383	    for (const c of stale) {
384	      console.error(`  - ${c.type} (${c.dateFormatted}) - start date ${c.date}`);
385	    }
386	    console.error(
387	      `Update courses.json to remove past courses, or re-run with --allow-past-courses to bypass.`,
388	    );
389	    process.exit(1);
390	  }
391	
392	  return courses;
393	}
394	
395	function renderCoursesSection(courses: CourseEntry[]): string {
396	  const items = courses
397	    .map(
398	      (c) =>
399	        `  <li><strong>${escapeHtml(c.type)}</strong>, ${escapeHtml(c.dateFormatted)}, ${escapeHtml(c.location)} &ndash; <a href="${escapeAttr(c.url)}">Register</a></li>`,
400	    )
401	    .join("\n");
402	  return `<h2>Upcoming Courses</h2>\n<ul>\n${items}\n</ul>`;
403	}
404	
405	function escapeHtml(s: string): string {
406	  return s
407	    .replace(/&/g, "&amp;")
408	    .replace(/</g, "&lt;")
409	    .replace(/>/g, "&gt;");
410	}
411	
412	function escapeAttr(s: string): string {
413	  return escapeHtml(s).replace(/"/g, "&quot;");
414	}
415	
416	// --- Confirmation prompt ---
417	
418	async function confirm(message: string): Promise<boolean> {
419	  const rl = createInterface({ input: process.stdin, output: process.stdout });
420	  const answer = await new Promise<string>((res) => {
421	    rl.question(message, (input) => {
422	      rl.close();
423	      res(input);
424	    });
425	  });
426	  return answer.trim().toLowerCase() === "yes";
427	}
428	
429	// --- Main ---
430	
431	async function main(): Promise<void> {
432	  const args = parseArgs();
433	
434	  console.log("=== Send Newsletter ===\n");
435	  console.log(`Content: ${args.contentPath}`);
436	
437	  const newsletter = parseNewsletter(args.contentPath);
438	  const courses = loadCourses(args.coursesPath, args.allowPastCourses);
439	
440	  console.log(`Subject: ${newsletter.subject}`);
441	  console.log(`Date:    ${newsletter.date}`);
442	  console.log(`Courses: ${courses.length}`);
443	
444	  // Render: prepend the code-owned greeting, Obsidian callouts → HTML, then the
445	  // whole markdown body → HTML, then append courses block, then inject into the
446	  // MJML wrapper.
447	  const bodyWithGreeting = withGreeting(newsletter.bodyMarkdown);
448	  const preProcessed = transformObsidianCallouts(bodyWithGreeting);
449	  const bodyHtml = marked.parse(preProcessed, { async: false }) as string;
450	  const coursesHtml = renderCoursesSection(courses);
451	  const fullBodyHtml = `${bodyHtml}\n${coursesHtml}`;
452	  const html = renderWrappedHtml(fullBodyHtml, WRAPPER_PATH);
453	
454	  const campaignName = `${newsletter.date} - ${newsletter.subject}`;
455	
456	  // Resolve the schedule before touching Cakemail, so a bad --schedule value
457	  // fails loudly instead of leaving a dangling draft.
458	  const schedule = args.scheduleDay ? resolveSchedule(args.scheduleDay) : undefined;
459	
460	  console.log(`\nCampaign name:    ${campaignName}`);
461	  console.log(`Audience list ID: ${NEWSLETTER_SUBSCRIBERS_LIST_ID}`);
462	  console.log(`Sender ID:        ${SENDER_ID_MARK}`);
463	  console.log(`Rendered HTML:    ${html.length} bytes`);
464	  if (schedule) console.log(`Scheduled send:   ${schedule.label}`);
465	
466	  const client = new CakemailClient();
467	
468	  // Duplicate guard. Every run creates a brand-new campaign (no idempotency),
469	  // so re-running this command is exactly how the whole list gets emailed
470	  // twice. Refuse if a campaign of the same name already exists in a committed
471	  // state (scheduled / delivering / delivered). No --force by design: delete
472	  // the existing campaign in Cakemail before re-running.
473	  const existing = await client.findCampaignsByName(
474	    NEWSLETTER_SUBSCRIBERS_LIST_ID,
475	    campaignName,
476	  );
477	  const committed = existing.filter(
478	    (c) => c.status !== "draft" && c.status !== "incomplete",
479	  );
480	  const drafts = existing.filter(
481	    (c) => c.status === "draft" || c.status === "incomplete",
482	  );
483	  if (committed.length > 0) {
484	    console.error(
485	      `\nABORTING: a campaign named "${campaignName}" already exists on the Newsletter Subscribers list:`,
486	    );
487	    for (const c of committed) {
488	      console.error(`  id=${c.id}  status=${c.status}`);
489	    }
490	    console.error(
491	      "Delete it in Cakemail, then re-run. (No --force: a duplicate here emails the whole list twice.)",
492	    );
493	    process.exit(1);
494	  }
495	  if (drafts.length > 0) {
496	    console.log(
497	      `\nNote: ${drafts.length} existing draft(s) with this name (harmless, do not send):`,
498	    );
499	    for (const c of drafts) {
500	      console.log(`  id=${c.id}  status=${c.status}`);
501	    }
502	  }
503	
504	  console.log("\n--- Creating draft campaign ---");
505	  const create = await client.createCampaign({
506	    name: campaignName,
507	    listId: parseInt(NEWSLETTER_SUBSCRIBERS_LIST_ID, 10),
508	    senderId: SENDER_ID_MARK,
509	    subject: newsletter.subject,
510	    html,
511	  });
512	  if (!create.ok || !create.id) {
513	    console.error(`  FAILED: ${create.error}`);
514	    process.exit(1);
515	  }
516	  const campaignId = create.id;
517	  console.log(`  Created campaign id=${campaignId}`);
518	
519	  const cleanup = async (reason: string): Promise<never> => {
520	    if (args.keepOnError) {
521	      console.error(
522	        `  Leaving draft in Cakemail (id=${campaignId}) because --keep-on-error is set.`,
523	      );
524	    } else {
525	      console.error(`  Deleting draft id=${campaignId} (${reason})…`);
526	      const del = await client.deleteCampaign(campaignId);
527	      if (!del.ok) {
528	        console.error(`  WARNING: delete failed: ${del.error}`);
529	      }
530	    }
531	    process.exit(1);
532	  };
533	
534	  if (args.testSend) {
535	    console.log(`\n--- Sending test to ${args.testSend} ---`);
536	    const test = await client.sendTestCampaign(campaignId, args.testSend);
537	    if (!test.ok) {
538	      console.error(`  FAILED: ${test.error}`);
539	      await cleanup("test send failed");
540	    }
541	    console.log("  Test sent. Review before proceeding.");
542	  }
543	
544	  if (schedule) {
545	    console.log(`\n--- Scheduling send for ${schedule.label} ---`);
546	    const sched = await client.scheduleCampaign(campaignId, schedule.unixSeconds);
547	    if (!sched.ok) {
548	      console.error(`  FAILED: ${sched.error}`);
549	      await cleanup("schedule failed");
550	    }
551	    console.log(`  Campaign ${campaignId} scheduled for ${schedule.label}.`);
552	    return;
553	  }
554	
555	  if (!args.send) {
556	    console.log(
557	      `\nDraft left in Cakemail. Review at the campaign UI, re-run with --send to dispatch now, or --schedule <day> to send at 10am ET.`,
558	    );
559	    console.log(`  Campaign ID: ${campaignId}`);
560	    return;
561	  }
562	
563	  const ok = await confirm(
564	    `\nSend campaign "${campaignName}" to the Newsletter Subscribers list NOW? Type "yes" to confirm: `,
565	  );
566	  if (!ok) {
567	    console.log("Aborted. Draft remains in Cakemail.");
568	    return;
569	  }
570	
571	  console.log("\n--- Scheduling for immediate send ---");
572	  const sched = await client.scheduleCampaign(campaignId);
573	  if (!sched.ok) {
574	    console.error(`  FAILED: ${sched.error}`);
575	    await cleanup("schedule failed");
576	  }
577	  console.log(`  Campaign ${campaignId} scheduled. Delivery in progress.`);
578	}
579	
580	main().catch((err) => {
581	  console.error("Error:", err);
582	  process.exit(1);
583	});
