import "./load-env";
import { readFileSync, existsSync } from "fs";
import { resolve } from "path";
import { createInterface } from "readline";
import { marked } from "marked";
import matter from "gray-matter";
import { CakemailClient } from "./cakemail-client";
import {
  renderWrappedHtml,
  transformObsidianCallouts,
} from "./render-email";
import {
  NEWSLETTER_SUBSCRIBERS_LIST_ID,
  SENDER_ID_MARK,
} from "../../shared/cakemail-constants";

const WRAPPER_PATH = resolve(
  __dirname,
  "../templates/course/post-wrapper.html",
);
const DEFAULT_COURSES_PATH = resolve(
  __dirname,
  "../newsletters/courses.json",
);

// --- Greeting ---
//
// The personalised greeting is owned by the code, NOT the author. Authors write
// only the body; this guarantees a correct Cakemail merge tag ships every time
// and removes the class of human error that mailed the whole list a literal
// "Hi [firstname,]," on 2026-06-26.
//
// `[firstname]` with NO comma is Cakemail's "no fallback" form: it renders the
// contact's first name, or blank when there isn't one. NEVER write an empty
// fallback "[firstname,]" — that is malformed and Cakemail prints the tag
// verbatim. A fallback word ("[firstname,there]") is deliberately not used:
// Mark prefers a bare greeting over a generic placeholder. (A contact with no
// first name therefore sees "Hi ," — to drop the dangling comma, change
// GREETING to `Hi ${FIRST_NAME_TAG}`.)
const FIRST_NAME_TAG = "[firstname]";
const GREETING = `Hi ${FIRST_NAME_TAG},`;

/**
 * Prepend the canonical greeting to the newsletter body.
 *
 * If the author still hand-wrote a greeting (out of habit, correct or
 * malformed), drop it first: a leading non-empty line containing "firstname"
 * (case-insensitive) is a merge-tag greeting attempt — that substring never
 * occurs in normal newsletter prose — so it is replaced rather than doubled.
 */
function withGreeting(bodyMarkdown: string): string {
  const lines = bodyMarkdown.split("\n");
  let start = 0;
  while (start < lines.length && lines[start].trim() === "") start += 1;
  if (start < lines.length && /firstname/i.test(lines[start])) {
    let end = start + 1;
    while (end < lines.length && lines[end].trim() === "") end += 1;
    lines.splice(start, end - start);
  }
  return `${GREETING}\n\n${lines.join("\n").trimStart()}`;
}

// --- Types ---

interface CliArgs {
  contentPath: string;
  coursesPath: string;
  testSend?: string;
  send: boolean;
  scheduleDay?: string;
  allowPastCourses: boolean;
  keepOnError: boolean;
}

interface NewsletterFrontmatter {
  subject: string;
  date: string | Date;
}

interface ParsedNewsletter {
  subject: string;
  date: string;
  bodyMarkdown: string;
}

interface CourseEntry {
  type: string;
  date: string;
  dateFormatted: string;
  location: string;
  url: string;
}

interface CoursesConfig {
  courses: CourseEntry[];
}

// --- CLI ---

function printUsage(): void {
  console.log(`
Usage:
  npm run send-newsletter -- --content newsletters/<file>.md [options]

Options:
  --content             Path to the newsletter markdown file (required)
  --courses             Path to courses JSON (default: newsletters/courses.json)
  --test-send <email>   Create the draft, then send a test copy to <email>. This
                        is how you preview: review it in your inbox and in the
                        Cakemail UI. Preview-only; cannot combine with --send or
                        --schedule (dispatch in a separate run).
  --send                After creating the draft (and any test), schedule for
                        immediate delivery. Prompts for confirmation.
  --schedule <day>      After creating the draft (and any test), schedule
                        delivery for the next Mon|Tue|Wed|Thu|Fri at 10:00 AM
                        Eastern. No confirmation prompt. Cannot combine with
                        --send.
  --allow-past-courses  Skip the stale-course validation
  --keep-on-error       On failure, leave the draft in Cakemail for inspection
                        (default: delete draft so the UI stays tidy)
  --help                Show this help

Workflow without --send (default):
  Creates a draft campaign in Cakemail. Review in the Cakemail UI and send
  from there, or re-run with --send once you are sure.
`);
}

function parseArgs(): CliArgs {
  const args = process.argv.slice(2);
  if (args.includes("--help") || args.includes("-h")) {
    printUsage();
    process.exit(0);
  }

  function getArg(name: string): string | undefined {
    const idx = args.indexOf(name);
    if (idx === -1 || idx + 1 >= args.length) return undefined;
    return args[idx + 1];
  }

  const contentPath = getArg("--content");
  if (!contentPath) {
    console.error("Error: --content is required.");
    printUsage();
    process.exit(1);
  }

  const scheduleDay = getArg("--schedule");
  const send = args.includes("--send");
  const testSend = getArg("--test-send");
  if (send && scheduleDay) {
    console.error(
      "Error: --send (immediate) and --schedule (future) are mutually exclusive.",
    );
    process.exit(1);
  }
  // --test-send is preview-only. Combining it with a dispatch flag is what
  // makes "I only tested it" actually commit a send. Force a separate run.
  if (testSend && (send || scheduleDay)) {
    console.error(
      "Error: --test-send is preview-only and cannot combine with --send or --schedule.\n" +
        "       Preview first, then dispatch in a separate run.",
    );
    process.exit(1);
  }

  return {
    contentPath,
    coursesPath: getArg("--courses") ?? DEFAULT_COURSES_PATH,
    testSend,
    send,
    scheduleDay,
    allowPastCourses: args.includes("--allow-past-courses"),
    keepOnError: args.includes("--keep-on-error"),
  };
}

// --- Schedule resolution ---
//
// `--schedule <day>` resolves to the soonest 10:00 AM Eastern on that weekday
// still in the future. The America/New_York IANA zone keeps "10am Eastern"
// correct year-round (EDT/UTC-4 in summer, EST/UTC-5 in winter).

const SCHEDULE_TZ = "America/New_York";
const SEND_HOUR_ET = 10;
const WEEKDAY_INDEX: Record<string, number> = {
  mon: 1,
  tue: 2,
  wed: 3,
  thu: 4,
  fri: 5,
};

interface ScheduledSend {
  unixSeconds: number;
  label: string; // human-readable ET datetime, for logging
}

/** Read numeric date/time parts of an instant as rendered in `timeZone`. */
function zonedParts(
  timeZone: string,
  at: Date,
  options: Intl.DateTimeFormatOptions,
): Record<string, number> {
  const parts: Record<string, number> = {};
  for (const p of new Intl.DateTimeFormat("en-US", {
    timeZone,
    hour12: false,
    ...options,
  }).formatToParts(at)) {
    if (p.type !== "literal") parts[p.type] = Number(p.value);
  }
  return parts;
}

/** UTC ms for a wall-clock time in `timeZone`, DST-correct. */
function wallClockToUtcMs(
  year: number,
  month0: number,
  day: number,
  hour: number,
  timeZone: string,
): number {
  const offsetMs = (ms: number): number => {
    const p = zonedParts(timeZone, new Date(ms), {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
    const asUtc = Date.UTC(
      p.year,
      p.month - 1,
      p.day,
      p.hour % 24,
      p.minute,
      p.second,
    );
    return asUtc - ms;
  };
  let ms = Date.UTC(year, month0, day, hour, 0, 0);
  const o1 = offsetMs(ms);
  ms -= o1;
  const o2 = offsetMs(ms);
  if (o2 !== o1) ms += o1 - o2;
  return ms;
}

function resolveSchedule(dayArg: string): ScheduledSend {
  const target = WEEKDAY_INDEX[dayArg.trim().toLowerCase().slice(0, 3)];
  if (target === undefined) {
    console.error(
      `Error: --schedule must be one of Mon, Tue, Wed, Thu, Fri (got "${dayArg}")`,
    );
    process.exit(1);
  }

  const now = new Date();
  const et = zonedParts(SCHEDULE_TZ, now, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
  });
  // 00:00-UTC anchor on ET's "today", safe for whole-day arithmetic.
  const anchor = Date.UTC(et.year, et.month - 1, et.day);
  const todayDow = new Date(anchor).getUTCDay();

  for (let i = 0; i <= 7; i++) {
    if ((todayDow + i) % 7 !== target) continue;
    if (i === 0 && et.hour % 24 >= SEND_HOUR_ET) continue; // 10am ET already passed
    const d = new Date(anchor + i * 86_400_000);
    const ms = wallClockToUtcMs(
      d.getUTCFullYear(),
      d.getUTCMonth(),
      d.getUTCDate(),
      SEND_HOUR_ET,
      SCHEDULE_TZ,
    );
    const label = new Intl.DateTimeFormat("en-US", {
      timeZone: SCHEDULE_TZ,
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "numeric",
      minute: "2-digit",
      timeZoneName: "short",
    }).format(new Date(ms));
    return { unixSeconds: Math.floor(ms / 1000), label };
  }
  // Unreachable: a weekday always recurs within 7 days.
  throw new Error("Could not resolve schedule date");
}

// --- Newsletter parsing ---

function parseNewsletter(filePath: string): ParsedNewsletter {
  if (!existsSync(filePath)) {
    console.error(`Error: newsletter file not found: ${filePath}`);
    process.exit(1);
  }

  const raw = readFileSync(filePath, "utf-8");
  const { data, content } = matter(raw);
  const fm = data as NewsletterFrontmatter;

  if (!fm.subject) {
    console.error("Error: frontmatter must include 'subject'");
    process.exit(1);
  }
  // gray-matter auto-parses YAML dates; coerce back to YYYY-MM-DD string.
  const dateStr =
    fm.date instanceof Date ? fm.date.toISOString().slice(0, 10) : String(fm.date ?? "");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
    console.error("Error: frontmatter must include 'date' in YYYY-MM-DD format");
    process.exit(1);
  }

  return {
    subject: String(fm.subject).trim(),
    date: dateStr,
    bodyMarkdown: content.trim(),
  };
}

// --- Courses ---

function todayYMD(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function loadCourses(coursesPath: string, allowPast: boolean): CourseEntry[] {
  if (!existsSync(coursesPath)) {
    console.error(
      `Error: courses file not found at ${coursesPath}. Every newsletter must include an Upcoming Courses block.`,
    );
    process.exit(1);
  }

  let config: CoursesConfig;
  try {
    config = JSON.parse(readFileSync(coursesPath, "utf-8"));
  } catch (err) {
    console.error(`Error: failed to parse ${coursesPath}: ${String(err)}`);
    process.exit(1);
  }

  const courses = config.courses ?? [];
  if (courses.length === 0) {
    console.error(
      `Error: ${coursesPath} has no courses. Every newsletter must include an Upcoming Courses block.`,
    );
    process.exit(1);
  }

  // Validate each entry has the fields we use.
  for (const c of courses) {
    if (!c.type || !c.date || !c.dateFormatted || !c.location || !c.url) {
      console.error(
        `Error: course entry is missing a required field (type, date, dateFormatted, location, url): ${JSON.stringify(c)}`,
      );
      process.exit(1);
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(c.date)) {
      console.error(
        `Error: course 'date' must be YYYY-MM-DD (got "${c.date}" on ${c.type})`,
      );
      process.exit(1);
    }
  }

  const today = todayYMD();
  const stale = courses.filter((c) => c.date < today);
  if (stale.length > 0 && !allowPast) {
    console.error(
      `Error: ${stale.length} course(s) in ${coursesPath} have already started:`,
    );
    for (const c of stale) {
      console.error(`  - ${c.type} (${c.dateFormatted}) - start date ${c.date}`);
    }
    console.error(
      `Update courses.json to remove past courses, or re-run with --allow-past-courses to bypass.`,
    );
    process.exit(1);
  }

  return courses;
}

function renderCoursesSection(courses: CourseEntry[]): string {
  const items = courses
    .map(
      (c) =>
        `  <li><strong>${escapeHtml(c.type)}</strong>, ${escapeHtml(c.dateFormatted)}, ${escapeHtml(c.location)} &ndash; <a href="${escapeAttr(c.url)}">Register</a></li>`,
    )
    .join("\n");
  return `<h2>Upcoming Courses</h2>\n<ul>\n${items}\n</ul>`;
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function escapeAttr(s: string): string {
  return escapeHtml(s).replace(/"/g, "&quot;");
}

// --- Confirmation prompt ---

async function confirm(message: string): Promise<boolean> {
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  const answer = await new Promise<string>((res) => {
    rl.question(message, (input) => {
      rl.close();
      res(input);
    });
  });
  return answer.trim().toLowerCase() === "yes";
}

// --- Main ---

async function main(): Promise<void> {
  const args = parseArgs();

  console.log("=== Send Newsletter ===\n");
  console.log(`Content: ${args.contentPath}`);

  const newsletter = parseNewsletter(args.contentPath);
  const courses = loadCourses(args.coursesPath, args.allowPastCourses);

  console.log(`Subject: ${newsletter.subject}`);
  console.log(`Date:    ${newsletter.date}`);
  console.log(`Courses: ${courses.length}`);

  // Render: prepend the code-owned greeting, Obsidian callouts → HTML, then the
  // whole markdown body → HTML, then append courses block, then inject into the
  // MJML wrapper.
  const bodyWithGreeting = withGreeting(newsletter.bodyMarkdown);
  const preProcessed = transformObsidianCallouts(bodyWithGreeting);
  const bodyHtml = marked.parse(preProcessed, { async: false }) as string;
  const coursesHtml = renderCoursesSection(courses);
  const fullBodyHtml = `${bodyHtml}\n${coursesHtml}`;
  const html = renderWrappedHtml(fullBodyHtml, WRAPPER_PATH);

  const campaignName = `${newsletter.date} - ${newsletter.subject}`;

  // Resolve the schedule before touching Cakemail, so a bad --schedule value
  // fails loudly instead of leaving a dangling draft.
  const schedule = args.scheduleDay ? resolveSchedule(args.scheduleDay) : undefined;

  console.log(`\nCampaign name:    ${campaignName}`);
  console.log(`Audience list ID: ${NEWSLETTER_SUBSCRIBERS_LIST_ID}`);
  console.log(`Sender ID:        ${SENDER_ID_MARK}`);
  console.log(`Rendered HTML:    ${html.length} bytes`);
  if (schedule) console.log(`Scheduled send:   ${schedule.label}`);

  const client = new CakemailClient();

  // Duplicate guard. Every run creates a brand-new campaign (no idempotency),
  // so re-running this command is exactly how the whole list gets emailed
  // twice. Refuse if a campaign of the same name already exists in a committed
  // state (scheduled / delivering / delivered). No --force by design: delete
  // the existing campaign in Cakemail before re-running.
  const existing = await client.findCampaignsByName(
    NEWSLETTER_SUBSCRIBERS_LIST_ID,
    campaignName,
  );
  const committed = existing.filter(
    (c) => c.status !== "draft" && c.status !== "incomplete",
  );
  const drafts = existing.filter(
    (c) => c.status === "draft" || c.status === "incomplete",
  );
  if (committed.length > 0) {
    console.error(
      `\nABORTING: a campaign named "${campaignName}" already exists on the Newsletter Subscribers list:`,
    );
    for (const c of committed) {
      console.error(`  id=${c.id}  status=${c.status}`);
    }
    console.error(
      "Delete it in Cakemail, then re-run. (No --force: a duplicate here emails the whole list twice.)",
    );
    process.exit(1);
  }
  if (drafts.length > 0) {
    console.log(
      `\nNote: ${drafts.length} existing draft(s) with this name (harmless, do not send):`,
    );
    for (const c of drafts) {
      console.log(`  id=${c.id}  status=${c.status}`);
    }
  }

  console.log("\n--- Creating draft campaign ---");
  const create = await client.createCampaign({
    name: campaignName,
    listId: parseInt(NEWSLETTER_SUBSCRIBERS_LIST_ID, 10),
    senderId: SENDER_ID_MARK,
    subject: newsletter.subject,
    html,
  });
  if (!create.ok || !create.id) {
    console.error(`  FAILED: ${create.error}`);
    process.exit(1);
  }
  const campaignId = create.id;
  console.log(`  Created campaign id=${campaignId}`);

  const cleanup = async (reason: string): Promise<never> => {
    if (args.keepOnError) {
      console.error(
        `  Leaving draft in Cakemail (id=${campaignId}) because --keep-on-error is set.`,
      );
    } else {
      console.error(`  Deleting draft id=${campaignId} (${reason})…`);
      const del = await client.deleteCampaign(campaignId);
      if (!del.ok) {
        console.error(`  WARNING: delete failed: ${del.error}`);
      }
    }
    process.exit(1);
  };

  if (args.testSend) {
    console.log(`\n--- Sending test to ${args.testSend} ---`);
    const test = await client.sendTestCampaign(campaignId, args.testSend);
    if (!test.ok) {
      console.error(`  FAILED: ${test.error}`);
      await cleanup("test send failed");
    }
    console.log("  Test sent. Review before proceeding.");
  }

  if (schedule) {
    console.log(`\n--- Scheduling send for ${schedule.label} ---`);
    const sched = await client.scheduleCampaign(campaignId, schedule.unixSeconds);
    if (!sched.ok) {
      console.error(`  FAILED: ${sched.error}`);
      await cleanup("schedule failed");
    }
    console.log(`  Campaign ${campaignId} scheduled for ${schedule.label}.`);
    return;
  }

  if (!args.send) {
    console.log(
      `\nDraft left in Cakemail. Review at the campaign UI, re-run with --send to dispatch now, or --schedule <day> to send at 10am ET.`,
    );
    console.log(`  Campaign ID: ${campaignId}`);
    return;
  }

  const ok = await confirm(
    `\nSend campaign "${campaignName}" to the Newsletter Subscribers list NOW? Type "yes" to confirm: `,
  );
  if (!ok) {
    console.log("Aborted. Draft remains in Cakemail.");
    return;
  }

  console.log("\n--- Scheduling for immediate send ---");
  const sched = await client.scheduleCampaign(campaignId);
  if (!sched.ok) {
    console.error(`  FAILED: ${sched.error}`);
    await cleanup("schedule failed");
  }
  console.log(`  Campaign ${campaignId} scheduled. Delivery in progress.`);
}

main().catch((err) => {
  console.error("Error:", err);
  process.exit(1);
});

